import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    my_c = 0
    op_c = 0
    for a in me:
        if a == 'C':
            my_c += 1
    for a in op:
        if a == 'C':
            op_c += 1
    op_d = n - op_c

    # Near the end, extract value from persistently cooperative opponents.
    if n >= 95:
        if op_d <= max(1, n // 12):
            if n >= 98:
                return 'D'
            if op[-1] == 'C':
                return 'D' if rng.random() < 0.6 else 'C'
            return 'D'
        if op_d >= n - 1:
            return 'D'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Never allow permanent lock into DD: after long mutual defection, probe.
    if op[-1] == 'D' and me[-1] == 'D':
        k = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D' and history[i][1] == 'D':
                k += 1
            else:
                break
        if k >= 4:
            return 'C'
        if k >= 2 and rng.random() < 0.25:
            return 'C'

    # Against a mostly cooperative opponent: stay nice, retaliate only recent defection.
    if op_c >= n - max(1, n // 10):
        if op[-1] == 'D':
            # one-shot retaliation, then likely forgive
            if op_d >= 2:
                return 'D'
            return 'C'
        return 'C'

    # Against a mostly defective opponent: defend but probe for a restart.
    if op_c <= n // 3:
        if op[-1] == 'D':
            if op_c >= 1 and rng.random() < 0.12:
                return 'C'
            return 'D'
        # opponent cooperated: verify quickly, don't get fooled into long DD
        if me[-1] == 'D':
            return 'C'
        return 'C'

    last_me = me[-1]
    last_op = op[-1]

    # Mid-game reciprocal regime.
    if last_op == 'D':
        if last_me == 'D':
            return 'C'
        # forgive occasionally if opponent's overall record is decent
        if op_c * 2 >= n and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent cooperated last. Occasionally probe to punish over-cooperators,
    # but keep it rare so long CC streaks are preserved.
    if n < 90:
        if op_d == 0 and n >= 20 and n < 80 and rng.random() < 0.04:
            return 'D'
        if op_c * 3 >= n * 2 and rng.random() < 0.03:
            return 'D'
    return 'C'
